import json
import sys
from pathlib import Path

transcripts = [
    "/Users/mcneillm/.gemini/antigravity/brain/78225928-6cb1-4603-b2a9-e4b2495a5ec3/.system_generated/logs/transcript.jsonl",
    "/Users/mcneillm/.gemini/antigravity/brain/131dd1e2-36c6-4fc9-aa2e-0977f9f2463b/.system_generated/logs/transcript.jsonl",
    "/Users/mcneillm/.gemini/antigravity/brain/f92718b3-f7cc-49c2-982c-85390933d083/.system_generated/logs/transcript.jsonl",
    "/Users/mcneillm/.gemini/antigravity/brain/282eddf4-b2ee-42d0-8cd6-fec8c6d221de/.system_generated/logs/transcript.jsonl",
    "/Users/mcneillm/.gemini/antigravity/brain/e4971402-7eeb-4656-b062-7b668f3b6a59/.system_generated/logs/transcript.jsonl",
]

def analyze_transcript(path_str):
    p = Path(path_str)
    conv_id = p.parent.parent.parent.name
    print(f"\n==================================================")
    print(f"Transcript: {conv_id}")
    print(f"==================================================")
    if not p.exists():
        print(f"File not found: {p}")
        return

    steps = []
    with open(p, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                try:
                    steps.append(json.loads(line))
                except Exception as e:
                    pass

    print(f"Total steps: {len(steps)}")
    if not steps:
        return

    first_step = steps[0]
    last_step = steps[-1]
    print(f"Start time: {first_step.get('created_at')}")
    print(f"End time: {last_step.get('created_at')}")

    # Extract user input (prompt)
    user_prompts = []
    for s in steps:
        if s.get("type") == "USER_INPUT":
            content = s.get("content", "")
            user_prompts.append(content[:500])

    print(f"User Prompt (first 500 chars):")
    if user_prompts:
        print(user_prompts[0])
    else:
        print("No USER_INPUT found.")

    # Tool calls summary
    tool_counts = {}
    commands = []
    test_runs = []
    pr_creates = []
    for s in steps:
        tool_calls = s.get("tool_calls", [])
        for tc in tool_calls:
            name = tc.get("toolAction") or tc.get("name") or "unknown"
            # In transcript.jsonl, structure might have tool name in various fields
            tool_name = tc.get("toolAction") or str(tc.get("name", ""))
            tool_counts[tool_name] = tool_counts.get(tool_name, 0) + 1
            args = tc.get("args") or tc.get("arguments") or tc.get("parameters") or {}
            # check command line
            cmd = args.get("CommandLine") or ""
            if cmd:
                commands.append(cmd)
                if "test" in cmd or "pio" in cmd:
                    test_runs.append(cmd)
                if "pr create" in cmd or "gh pr" in cmd:
                    pr_creates.append(cmd)

    print("\nTool counts summary:")
    for k, v in sorted(tool_counts.items(), key=lambda x: -x[1])[:10]:
        print(f"  {k}: {v}")

    if test_runs:
        print("\nTest commands observed:")
        for t in test_runs:
            print(f"  {t[:120]}")

    if pr_creates:
        print("\nPR commands observed:")
        for prc in pr_creates:
            print(f"  {prc[:120]}")

    # Last assistant responses
    assistant_responses = []
    for s in reversed(steps):
        if s.get("type") == "PLANNER_RESPONSE":
            content = s.get("content", "")
            if content:
                assistant_responses.append(content)
                if len(assistant_responses) >= 2:
                    break

    print("\nLast Assistant Response (excerpt):")
    if assistant_responses:
        print(assistant_responses[0][:600])

if __name__ == "__main__":
    for t in transcripts:
        analyze_transcript(t)
